/*
 * File:  bsp_start.c
 *
 * Purpose:
 *   Host-independent FreeRTOS OSAL BSP entry point and support code, shared
 *   across every FreeRTOS host-specific BSP (e.g. the POSIX simulator port).
 *   Each consumer compiles this file itself against its own
 *   FreeRTOSConfigPlatform.h (generated by osal_freertos_platform()), since
 *   some of the code below sizes static buffers from config values that
 *   legitimately differ per host.
 */

#include <stdlib.h>
#include <string.h>

#include "FreeRTOS.h"
#include "task.h"
#include "timers.h"
#include "semphr.h"

#include "osapi-common.h"
#include "bsp-impl.h"

#include "generic_freertos_bsp_internal.h"

/*----------------------------------------------------------------
   OS_BSP_StorageConfig

   Pointer to the littlefs configuration for the BSP's storage device. The
   storage source selected at build time (OSAL_FREERTOS_STORAGE_TARGET)
   defines it, so the BSP does not know what the device looks like. The
   pointer is valid for the life of the program and must not be modified.

   The cache_size must not exceed OS_FREERTOS_LFS_FILE_CACHE_SIZE (see
   freertos/inc/os-impl-filesys.h), which is what each open file reserves.
 ------------------------------------------------------------------*/
extern const struct lfs_config *const OS_BSP_StorageConfig;

/* Reports the overflowing task and halts, never returns (bsp_console.c) */
void OS_FreeRTOS_StackOverflow(const char *TaskName);

/* Reports the exit status and halts, never returns (bsp_console.c) */
void OS_FreeRTOS_ApplicationExit(int Status);

OS_BSP_GenericFreeRTOSGlobalData_t OS_BSP_GenericFreeRTOSGlobal;

/*----------------------------------------------------------------
   OS_BSP_Lock_Impl
   See full description in header
 ------------------------------------------------------------------*/
void OS_BSP_Lock_Impl(void)
{
    xSemaphoreTake(OS_BSP_GenericFreeRTOSGlobal.ConsoleMutex, portMAX_DELAY);
}

/*----------------------------------------------------------------
   OS_BSP_Unlock_Impl
   See full description in header
 ------------------------------------------------------------------*/
void OS_BSP_Unlock_Impl(void)
{
    xSemaphoreGive(OS_BSP_GenericFreeRTOSGlobal.ConsoleMutex);
}

/*----------------------------------------------------------------
   OS_BSP_GetReturnStatus()

    Helper function to convert an OSAL status code into
    a code suitable for returning to the OS.
 ------------------------------------------------------------------*/
static int OS_BSP_GetReturnStatus(void)
{
    int retcode;

    switch (OS_BSP_Global.AppStatus)
    {
        case OS_SUCCESS:
            retcode = EXIT_SUCCESS;
            break;

        case OS_ERROR:
            retcode = EXIT_FAILURE;
            break;

        default:
            retcode = OS_BSP_Global.AppStatus & 0x7F;
            break;
    }

    return retcode;
}

/*----------------------------------------------------------------
   OS_BSP_Exit

    Ends the application. A port that implements vPortEndScheduler (the
    GCC_POSIX port, which returns control to main()) ends the scheduler.
    Every other port has nothing to return to (the Cortex-M ports assert in
    vPortEndScheduler), so it reports the status and halts. A port says it can
    end the scheduler through OSAL_FREERTOS_PORT_ENDS_SCHEDULER, defined per
    port in generic-freertos/config/CMakeLists.txt.
 ------------------------------------------------------------------*/
static inline void OS_BSP_Exit(int Status)
{
#if defined(OSAL_FREERTOS_PORT_ENDS_SCHEDULER)
    (void)Status;

    vTaskEndScheduler();
#else
    OS_FreeRTOS_ApplicationExit(Status);
#endif
}

/*----------------------------------------------------------------
   OS_BSP_Shutdown_Impl
   See full description in header
 ------------------------------------------------------------------*/
void OS_BSP_Shutdown_Impl(void)
{
    OS_BSP_Exit(OS_BSP_GetReturnStatus());
}

/*----------------------------------------------------------------
   FreeRTOS static-allocation hooks

   Required because FreeRTOSConfig.h sets configSUPPORT_STATIC_ALLOCATION
   and configCHECK_FOR_STACK_OVERFLOW - FreeRTOS calls these rather than
   allocating the idle/timer task memory itself, and reports a detected
   stack overflow through the hook instead of a fixed action.
 ------------------------------------------------------------------*/
void vApplicationGetIdleTaskMemory(StaticTask_t          **ppxIdleTaskTCBBuffer,
                                   StackType_t           **ppxIdleTaskStackBuffer,
                                   configSTACK_DEPTH_TYPE *puxIdleTaskStackSize)
{
    static StaticTask_t IdleTaskTCBBuffer;
    static StackType_t  IdleTaskStackBuffer[configMINIMAL_STACK_SIZE];

    *ppxIdleTaskTCBBuffer   = &IdleTaskTCBBuffer;
    *ppxIdleTaskStackBuffer = IdleTaskStackBuffer;
    *puxIdleTaskStackSize   = configMINIMAL_STACK_SIZE;
}

void vApplicationGetTimerTaskMemory(StaticTask_t          **ppxTimerTaskTCBBuffer,
                                    StackType_t           **ppxTimerTaskStackBuffer,
                                    configSTACK_DEPTH_TYPE *puxTimerTaskStackSize)
{
    static StaticTask_t TimerTaskTCBBuffer;
    static StackType_t  TimerTaskStackBuffer[configTIMER_TASK_STACK_DEPTH];

    *ppxTimerTaskTCBBuffer   = &TimerTaskTCBBuffer;
    *ppxTimerTaskStackBuffer = TimerTaskStackBuffer;
    *puxTimerTaskStackSize   = configTIMER_TASK_STACK_DEPTH;
}

/*
 * The kernel calls this from inside its task switch, with the scheduler's lists
 * in use, so it must not change kernel state: vTaskEndScheduler() there would
 * delete the idle task the switch is about to pick from. It halts instead.
 */
// pcTaskName must stay non-const to match the kernel's declaration of this hook
// cppcheck-suppress constParameterPointer
void vApplicationStackOverflowHook(TaskHandle_t xTask, char *pcTaskName)
{
    (void)xTask;

    OS_FreeRTOS_StackOverflow(pcTaskName);
}

/*----------------------------------------------------------------
   OS_BSP_StartupTask

   FreeRTOS does not run any created task until vTaskStartScheduler()
   is called, and that call does not return during normal operation -
   so the application entry points must run from within a task of
   their own, rather than directly from main().
 ------------------------------------------------------------------*/
// pvParameters must stay non-const to match FreeRTOS's TaskFunction_t signature
// cppcheck-suppress constParameterCallback
static void OS_BSP_StartupTask(void *pvParameters)
{
    /* This task only runs once the scheduler is up, see SchedulerRan in generic_freertos_bsp_internal.h */
    OS_BSP_GenericFreeRTOSGlobal.SchedulerRan = true;

    /*
     * Call application specific entry point.
     * This should set up all user tasks and resources, then return
     */
    OS_Application_Startup();

    /*
     * OS_Application_Run() implements the background task.
     * The user application may provide this, or a default implementation
     * is used which just calls OS_IdleLoop().
     */
    OS_Application_Run();

    /* The application has finished */
    OS_BSP_Shutdown_Impl();
}

/******************************************************************************
**
**  Purpose:
**    BSP Application entry point.
**
**  Arguments:
**    (none)
**
**  Return:
**    (none)
*/
int main(int argc, char *argv[])
{
    /*
     * Initially clear the global objects
     */
    memset(&OS_BSP_Global, 0, sizeof(OS_BSP_Global));
    memset(&OS_BSP_GenericFreeRTOSGlobal, 0, sizeof(OS_BSP_GenericFreeRTOSGlobal));

    /*
     * Save the argc/argv arguments for future use.
     */
    OS_BSP_Global.ArgC = argc;
    OS_BSP_Global.ArgV = argv;

    OS_BSP_GenericFreeRTOSGlobal.ConsoleMutex =
        xSemaphoreCreateMutexStatic(&OS_BSP_GenericFreeRTOSGlobal.ConsoleMutexBuffer);

    /*
     * Create the initial task, which performs application startup and then
     * runs the application's main loop.  vTaskStartScheduler() below is what
     * actually begins executing it.
     */
    if (xTaskCreate(OS_BSP_StartupTask,
                    "OSAL_Startup",
                    (configMINIMAL_STACK_SIZE * 4),
                    NULL,
                    (configMAX_PRIORITIES / 2),
                    NULL)
        != pdPASS)
    {
        /* Without this task the scheduler would run forever with nothing to do */
        return EXIT_FAILURE;
    }

    vTaskStartScheduler();

    /*
     * Only reached if the scheduler could not start (e.g. insufficient heap
     * for the idle/timer tasks), or if it was ended after running. Failing to
     * start is an error exit, and no application ran to set a status of its own;
     * an ended scheduler keeps the status the application set.
     */
    if (!OS_BSP_GenericFreeRTOSGlobal.SchedulerRan)
    {
        OS_BSP_SetExitCode(OS_ERROR);
    }

    return OS_BSP_GetReturnStatus();
}
